CREATE TRIGGER "trg_ticket_messages_last_updated_ts" BEFORE UPDATE ON "ticket_messages" FOR EACH ROW EXECUTE FUNCTION "set_ticket_messages_last_updated_ts"();
CREATE OR REPLACE FUNCTION "set_user_permissions_created_by_ts"() RETURNS trigger AS $$
BEGIN NEW."created_by" = now(); RETURN NEW; END;
$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS "trg_user_permissions_created_by_ts" ON "user_permissions";
CREATE TRIGGER "trg_user_permissions_created_by_ts" BEFORE UPDATE ON "user_permissions" FOR EACH ROW EXECUTE FUNCTION "set_user_permissions_created_by_ts"();
CREATE OR REPLACE FUNCTION "set_wallet_transactions_last_updated_ts"() RETURNS trigger AS $$
BEGIN NEW."last_updated" = now(); RETURN NEW; END;
$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS "trg_wallet_transactions_last_updated_ts" ON "wallet_transactions";
CREATE TRIGGER "trg_wallet_transactions_last_updated_ts" BEFORE UPDATE ON "wallet_transactions" FOR EACH ROW EXECUTE FUNCTION "set_wallet_transactions_last_updated_ts"();
